import{z as l,x as i,o as A,c as d,q as n,j as s,D as e,d as r,s as o,S as B,b as a}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"瞬态执行对照","description":"","frontmatter":{"title":"瞬态执行对照","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/transient-exec.md","filePath":"cs/transient-exec.md","lastUpdated":1791063341000}'),p={name:"cs/transient-exec.md"};function c(C,E,D,h,m,F){const t=i("Mermaid");return A(),d("div",null,[E[2]||(E[2]=n('<h1 id="瞬态执行对照" tabindex="-1">瞬态执行对照 <a class="header-anchor" href="#瞬态执行对照" aria-label="Permalink to &quot;瞬态执行对照&quot;">​</a></h1><div class="epigraph"><p>预测执行可以在架构状态回滚之后，仍在缓存与缓冲里留下可测差异；隔离规格若只写寄存器与页表，会漏掉这一层。</p><footer>—— 据 Kocher 等与 Lipp 等对瞬态执行的公开叙述；Anderson 对侧信道扩展威胁模型</footer></div><p><a href="/cs/side-channel">上一课</a>把时间、缓存、功耗标进模型。本课不重列计时。缺口是微结构：<a href="/cs/ooo-rob">乱序</a> 与<a href="/cs/control-hazard-predict">分支预测</a> 会让指令在提交前执行，失败路径被丢弃，但缓存占用还在。对照的是机制与防御（隔离、刷新、栅栏、关预测），不是可运行的探测程序。TLS 握手下一课回到协议。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>侧信道课留下「非规格输出」。瞬态执行：错误预测或故障路径上的加载仍会填缓存，架构寄存器随后像没发生。跨特权、跨进程的机密可能被编码进命中/未命中。缺口是<strong>把组成课的预测器接到威胁模型</strong>，并声明本栏只讲机制与缓解，不提供复现步骤。</p><p><span class="marginnote">术语翻译：瞬态执行就是「做了又当作没做」的指令——寄存器结果会回滚，但执行途中摸过的缓存不回滚。攻击者读的不是回滚掉的值，而是缓存留下的脚印。</span></p><p><span class="marginnote">Meltdown 式故障抑制与 Spectre 式预测是两条公开叙述。防御包括内核页隔离、微码、序列化、分区缓存。没有一种栅栏取消全部预测收益。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>设计：敏感代码常时间、不按秘密分支、不按秘密索引缓存。系统：地址空间隔离加强、共享页谨慎、SMT 共核当作同一信任域或关掉。规格：把「架构上看不见」改成「微结构也要预算」。本课不给测量代码。</p><p><span class="marginnote">常见误区：以为打上补丁就一劳永逸。栅栏与关预测是拿性能换安全——一次序列化就少一段乱序窗口，热循环可能慢百分之几十；而且没有一种栅栏能取消全部预测收益。</span></p>',10)),(A(),s(B,null,{default:e(()=>[o(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20SPEC%5B%22%E9%A2%84%E6%B5%8B%20%2F%20%E6%95%85%E9%9A%9C%E8%B7%AF%E5%BE%84%22%5D%20--%3E%20ARCH%5B%22%E6%9E%B6%E6%9E%84%E7%8A%B6%E6%80%81%E5%9B%9E%E6%BB%9A%22%5D%0A%20%20SPEC%20--%3E%20UARCH%5B%22%E7%BC%93%E5%AD%98%E7%AD%89%E4%BB%8D%E5%8F%98%E5%8C%96%22%5D%0A%20%20UARCH%20--%3E%20DEF%5B%22%E9%9A%94%E7%A6%BB%20%2F%20%E6%A0%85%E6%A0%8F%20%2F%20%E5%88%B7%E6%96%B0%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[r(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[r("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"瞬态执行让 CIA 的 C 在「页表已隔离」时仍可能失败。引用监视器看不到缓存。后课 TLS 保护的是链路上的字节，不自动保护同机微结构。组成课的性能机制在此变成安全边界。",-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"直觉类比：把缓存想成访客签名簿——访客（瞬态指令）虽被请出去（回滚），签名却留在簿上；细心的对手逐页比对谁签过名，就知道他去过哪些房间。")],-1)),(A(),s(B,null,{default:e(()=>[o(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20TRAIN%5B%22%E5%85%88%E8%AE%AD%E7%BB%83%E5%88%86%E6%94%AF%E9%A2%84%E6%B5%8B%E5%99%A8%3Cbr%2F%3E%E8%AE%A9%E5%88%86%E6%94%AF%E5%A4%9A%E6%AC%A1%E8%B5%B0%E7%9C%9F%E8%B7%AF%E5%BE%84%22%5D%20--%3E%20MIS%5B%22%E7%9C%9F%E5%AE%9E%E8%BE%93%E5%85%A5%E6%8D%A2%E6%88%90%E7%A7%98%E5%AF%86%E5%80%BC%3Cbr%2F%3E%E9%A2%84%E6%B5%8B%E9%94%99%E8%AF%AF%E4%BD%86%E6%8C%87%E4%BB%A4%E4%BB%8D%E6%89%A7%E8%A1%8C%22%5D%0A%20%20MIS%20--%3E%20LEAK%5B%22%E7%9E%AC%E6%80%81%E5%8A%A0%E8%BD%BD%E7%A7%98%E5%AF%86%3Cbr%2F%3E%E7%94%A8%E5%AE%83%E5%81%9A%E4%B8%8B%E6%A0%87%E8%AE%BF%E9%97%AE%E6%95%B0%E7%BB%84%22%5D%0A%20%20LEAK%20--%3E%20CACHE%5B%22%E5%AF%B9%E5%BA%94%E7%BC%93%E5%AD%98%E8%A1%8C%E8%A2%AB%E5%A1%AB%E5%85%A5%3Cbr%2F%3E%E5%AF%84%E5%AD%98%E5%99%A8%E9%9A%8F%E5%90%8E%E5%9B%9E%E6%BB%9A%E5%A6%82%E6%97%A0%E4%BA%8B%22%5D%0A%20%20CACHE%20--%3E%20PROBE%5B%22%E6%B5%8B%E5%90%84%E7%BC%93%E5%AD%98%E8%A1%8C%E5%91%BD%E4%B8%AD%E6%97%B6%E9%97%B4%3Cbr%2F%3E%E5%91%BD%E4%B8%AD%E7%9A%84%E4%B8%8B%E6%A0%87%E5%8D%B3%E7%A7%98%E5%AF%86%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[r(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=n('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把每一次公开变体的名字列成考试。网络上如何协商密钥与证书，下一课 TLS 握手。</p><p>后课默认：侧信道含瞬态执行。会话保密从握手开始在链路上收口。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>瞬态执行把预测器变成泄露面。</li><li>防御是隔离与限制推测，代价是性能。</li><li>TLS 握手下一课。</li><li>出处：公开的 Spectre/Meltdown 叙述；Kocher 计时一线；Anderson。</li></ul>',5))])}const _=l(p,[["render",c]]);export{u as __pageData,_ as default};
